<script lang="ts">
import {onMount,untrack} from 'svelte';import {call,type Frame} from '../lib/devtools';
import {invoke} from '@tauri-apps/api/core';
let {conversationId,platform,preferredDeviceId=''}:{conversationId:string;platform:'ios'|'android';preferredDeviceId?:string}=$props();let devices=$state<any[]>([]),selected=$state(''),frame=$state<Frame|null>(null),error=$state(''),reason=$state(''),text=$state(''),busy=$state(false),appPath=$state(''),bundleId=$state('');let alive=true,start:{x:number;y:number}|null=null;
$effect(()=>{const id=preferredDeviceId;if(id)untrack(()=>{selected=id;frame=null;void refresh();});});
const rpc=(action:string,p={})=>call(conversationId,'mobile',action,{platform,device_id:selected,...p});
async function refresh(){try{const v=await rpc('list');if(!alive)return;devices=v.devices;reason=v.reason??v.notes?.join(' ')??'';if(!selected)selected=devices.find(d=>d.state==='booted')?.id??devices[0]?.id??'';}catch(e){error=String(e);}}
async function action(name:string,p={}){busy=true;try{const result=await rpc(name,p);if(name==='boot'&&result.device_id)selected=result.device_id;error='';if(name==='boot'||name==='shutdown'){frame=null;await refresh();}}catch(e){if(alive)error=String(e);}finally{busy=false;}}
onMount(()=>{let timer:ReturnType<typeof setTimeout>;async function poll(){const id=selected;try{if(id&&devices.find(d=>d.id===id)?.state==='booted'){const f=await rpc('screenshot');if(alive&&id===selected)frame=f;}}catch(e){if(alive)error=String(e);}if(alive)timer=setTimeout(poll,800);}refresh().then(poll);return()=>{alive=false;clearTimeout(timer);};});
function position(e:PointerEvent){const r=e.currentTarget instanceof HTMLElement?e.currentTarget.getBoundingClientRect():null;return r?{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}:{x:0,y:0};}
async function saveScreenshot(){if(!frame)return;try{await invoke('save_tool_screenshot',{data:frame.data});}catch(e){if(alive)error=String(e);}}
</script>
<div class="devtools-row"><select aria-label="Device" value={selected} onchange={e=>{selected=e.currentTarget.value;frame=null;}}>{#each devices as d}<option value={d.id}>{d.name} · {d.runtime??d.platform} · {d.state}</option>{/each}</select><button onclick={refresh}>↻</button></div>
<div class="devtools-row"><button disabled={busy||!selected} onclick={()=>action('boot')}>Start</button><button disabled={busy||!selected} onclick={()=>action('shutdown')}>Shut down</button><button disabled={!frame} onclick={()=>action('key',{key:'home'})}>Home</button>{#if platform==='android'}<button disabled={!frame} onclick={()=>action('key',{key:'back'})}>Back</button>{/if}</div>
{#if reason}<p>{reason}</p>{/if}{#if error}<p role="alert">{error}</p>{/if}
{#if frame}<button type="button" class="device-screen" aria-label="Interactive device screen" onpointerdown={e=>{start=position(e);e.currentTarget.setPointerCapture(e.pointerId);}} onpointerup={e=>{const end=position(e);if(start){const moved=Math.hypot(end.x-start.x,end.y-start.y)>.02;void action(moved?'swipe':'tap',moved?{...start,x2:end.x,y2:end.y,duration_ms:400}:end);start=null;}}}><img draggable="false" alt="Current device screen" src={`data:${frame.mime_type};base64,${frame.data}`}/></button>{:else}<p class="devtools-empty">Select and start a device to test your app. {platform==='ios'?'Xcode and an iOS Simulator runtime are required.':'Android SDK platform tools and an emulator are required.'}</p>{/if}
<form class="devtools-row" onsubmit={e=>{e.preventDefault();void action('type',{text});text='';}}><input aria-label="Text to type on device" dir="auto" bind:value={text}/><button disabled={!frame}>Type</button></form>

<details><summary>Install and launch app</summary><form class="devtools-row" onsubmit={e=>{e.preventDefault();void action('install',{app_path:appPath});}}><input aria-label="App path inside project" placeholder="App path inside project" dir="ltr" bind:value={appPath}/><button disabled={busy||!selected||!appPath}>Install</button></form><form class="devtools-row" onsubmit={e=>{e.preventDefault();void action('launch',{bundle_id:bundleId});}}><input aria-label="App bundle ID" placeholder="com.example.app" dir="ltr" bind:value={bundleId}/><button disabled={busy||!selected||!bundleId}>Launch</button></form></details>
{#if frame}<button onclick={saveScreenshot}>Save screenshot</button>{/if}
